contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory _tos, uint[] memory v, bool wrongSender) public {
        require(_tos.length > 0);
        require(_tos.length == v.length);

        bool reverted;
        bool success;

        if (wrongSender) {
            address caller = address(this);
            bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
            (bool _s, ) = caller.call(abi.encodeWithSelector(id, c.from(), _tos[0], v[0] * 1000000000000000000));
            reverted = !_s;
            assert(reverted == true);
        } else {
            (reverted, success) = tryTransfer(_tos, v);
            assert(reverted == !success);
        }
    }

    function tryTransfer(address[] memory _tos, uint[] memory v) private returns (bool reverted, bool success) {
        try c.transfer(_tos, v) returns (bool s) {
            reverted = false;
            success = s;
        } catch {
            reverted = true;
            success = false;
        }
    }

    receive() external payable {}
}

